#!/usr/bin/env bash
set -euo pipefail
umask 077
project="${1:-/home/hobit/Documentos/Bot Belial/BOT_BELIAL_MVP_F0_F1_20260920/bot-belial}"
command -v python3 >/dev/null || { echo 'Python3 ausente'; exit 1; }
python3 - "$project" <<'BELIAL_PY'
import base64,zlib,json,sys,hashlib,os,datetime
from pathlib import Path
root=Path(sys.argv[1]).resolve()
if not (root/'Cargo.toml').is_file():sys.exit('Projeto nao encontrado: '+str(root))
patch=json.loads(zlib.decompress(base64.b64decode('')))
changes=[]
for rel,item in sorted(patch.items()):
 p=root/rel
 if Path(rel).is_absolute() or '..' in Path(rel).parts:sys.exit('Caminho invalido')
 if any(x.is_symlink() for x in [p,*p.parents] if x!=root):sys.exit('Link simbolico: '+str(p))
 data=base64.b64decode(item['data']); current=p.read_bytes() if p.exists() else None
 if current==data:continue
 digest=hashlib.sha256(current).hexdigest() if current is not None else None
 if digest not in item['old']:sys.exit('Arquivo alterado localmente; nada atualizado: '+str(p))
 changes.append((rel,data,current))
backup=root/'.belial-backups'/('pumpswap-p12-fix1-'+datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%dT%H%M%S')+'-'+str(os.getpid()))
if changes:
 backup.mkdir(parents=True)
 for rel,data,current in changes:
  if current is not None:
   p=backup/rel;p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes(current)
 (backup/'manifest.json').write_text(json.dumps({'modified':[r for r,d,c in changes],'new':[r for r,d,c in changes if c is None]},indent=2))
 for rel,data,current in changes:
  p=root/rel;p.parent.mkdir(parents=True,exist_ok=True)
  temp=p.with_name(p.name+'.r2-tmp-'+str(os.getpid()));temp.write_bytes(data)
  temp.chmod(0o755 if rel.endswith('.sh') else 0o644);os.replace(temp,p)
 print('Atualizacao aplicada. Backup:',backup)
else:print('Atualizacao PUMPSWAP P12 FIX1 ja aplicada.')
print('Configuracao, banco anterior e cache de compilacao preservados.')
BELIAL_PY
if [[ "${BELIAL_UPDATE_ONLY:-0}" == 1 ]]; then exit 0; fi
exec bash "$project/scripts/validar_p12.sh"
